import test from 'node:test';
import assert from 'node:assert/strict';
import { access, copyFile, readFile, writeFile } from 'node:fs/promises';
import { join } from 'node:path';
import { portabilityFixture } from './fixtures/portability.mjs';

// A seed whose Worker config is generated by its prepareData hook: export and import
// run that hook first, so a copy that never ran setup or build still completes. Its Vite
// configuration needs that generated file too, and the archive-path check resolves it.
async function seedWithGeneratedConfig(t) {
 const seed = await portabilityFixture(t, { generated: false }), adapter = join(seed.root, 'scripts/installer/local.mjs');
 const source = await readFile(adapter, 'utf8'), before = "operatorInstaller({ database: 'default-seed-reference', features: model.features })";
 assert.ok(source.includes(before));
 // The documented argv command form, run in the seed root like the other command hooks.
 await writeFile(adapter, source.replace(before, "operatorInstaller({ database: 'default-seed-reference', features: model.features, prepareData: [process.execPath, ['-e', \"require('node:fs').writeFileSync('prepared.txt', 'prepared')\"]] })"));
 const vite = join(seed.root, 'vite.config.ts');
 await writeFile(vite, "import { readFileSync } from 'node:fs';\nreadFileSync(new URL('./prepared.txt', import.meta.url));\n" + await readFile(vite, 'utf8'));
 return seed;
}

test('export and import run the seed prepareData hook first in a copy that never ran setup or build', async t => {
 const source = await seedWithGeneratedConfig(t), target = await seedWithGeneratedConfig(t);
 await assert.rejects(access(join(source.root, 'prepared.txt')));
 await source.run(['export', '--output', 'exports/a.rer']);
 assert.equal(await readFile(join(source.root, 'prepared.txt'), 'utf8'), 'prepared');
 await copyFile(join(source.root, 'exports/a.rer'), join(target.root, 'exports/a.rer'));
 await assert.rejects(access(join(target.root, 'prepared.txt')));
 await target.run(['import', '--input', 'exports/a.rer', '--yes']);
 assert.equal(await readFile(join(target.root, 'prepared.txt'), 'utf8'), 'prepared');
});
